from simulation import build
from runtime import solve, realize
from prose import render_book

BOOK = {'openings': [{'text': 'A breeze had knotted the red curtain into a lumpy red octopus. Mara blinked at it. “Our show has grown elbows!” Bo reached for the blue ribbon, while Nia grinned from behind the stage. Puck waited in his basket, ready for whatever ridiculous rescue might happen next.', 'when': [{'key': 'curtain.tangled', 'op': 'eq', 'value': True, 'at': 'initial'}, {'key': 'nia.brave', 'op': 'eq', 'value': 1, 'at': 'initial'}, {'key': 'bo.plan', 'op': 'eq', 'value': 'quiet', 'at': 'initial'}]}, {'text': 'The red curtain hung neatly, but Nia was hiding behind the low stool. “I want to perform,” she whispered to Mara, “only if the audience watches my shadows, not my nose.” Mara smiled. The blue ribbon lay in its basket, bright as a tiny river. “Then we’ll make a secret-sized show.”', 'when': [{'key': 'curtain.tangled', 'op': 'eq', 'value': False, 'at': 'initial'}, {'key': 'nia.brave', 'op': 'eq', 'value': 0, 'at': 'initial'}, {'key': 'bo.plan', 'op': 'eq', 'value': 'quiet', 'at': 'initial'}]}, {'text': 'Bo had drawn a finale so grand it needed three suns, seven trumpets, and an audience marching across the courtyard. Unfortunately, nobody had been invited close. “They’ll adore a parade!” he announced. Mara peered at the empty path. “Perhaps first we should tell them where the parade is.”', 'when': [{'key': 'curtain.tangled', 'op': 'eq', 'value': False, 'at': 'initial'}, {'key': 'nia.brave', 'op': 'eq', 'value': 1, 'at': 'initial'}, {'key': 'bo.plan', 'op': 'eq', 'value': 'grand', 'at': 'initial'}, {'key': 'audience.invited', 'op': 'eq', 'value': False, 'at': 'initial'}]}, {'text': 'The curtain was tidy, Nia was ready, and Bo had a very large idea. He waved at the empty courtyard as if it were packed with people. “My grand finale begins with a parade!” Mara whispered, “A parade needs feet.” Bo tied on his biggest smile and went to find some.', 'when': [{'key': 'curtain.tangled', 'op': 'eq', 'value': False, 'at': 'initial'}, {'key': 'nia.brave', 'op': 'eq', 'value': 1, 'at': 'initial'}, {'key': 'bo.plan', 'op': 'eq', 'value': 'grand', 'at': 'initial'}, {'key': 'audience.invited', 'op': 'eq', 'value': False, 'at': 'initial'}]}], 'scenes': [{'scene': 'greet_audience', 'role': 'bridge', 'variants': [{'text': 'Mara clapped twice, and the courtyard audience gathered with pockets full of crumbs and curiosity. Nia peeked out. Bo bowed so deeply his hair brushed the stage.', 'when': []}]}, {'scene': 'notice_curtain', 'role': 'beat', 'variants': [{'text': 'Mara tugged one corner of the curtain and discovered a breeze-tangled knot, with Puck caught in its folds like a kite waiting for a sneeze. “Nobody panic,” she said. “Except perhaps the octopus.”', 'when': [{'key': 'curtain.tangled', 'op': 'eq', 'value': True, 'at': 'after'}]}]}, {'scene': 'notice_bo_plan', 'role': 'beat', 'variants': [{'text': 'Mara found Bo’s plan beneath the paper sun: a grand finale with a parade, a fanfare, and “possibly one moon.” She looked toward the uninvited courtyard. Bo whispered, “The audience will want enormous.”', 'when': [{'key': 'bo.plan', 'op': 'eq', 'value': 'grand', 'at': 'after'}]}]}, {'scene': 'notice_invitation', 'role': 'beat', 'variants': [{'text': 'Mara discovered the important missing thing: nobody had invited the courtyard audience to follow the show. The path was empty except for one beetle. “Even the beetle needs a proper invitation,” she said.', 'when': [{'key': 'audience.invited', 'op': 'eq', 'value': False, 'at': 'after'}]}]}, {'scene': 'tell_nia_to_mara', 'role': 'beat', 'variants': [{'text': 'Nia leaned close and told Mara exactly what she wanted: a shadow role behind the curtain, where her paper hands could dance without every eye landing on her face. “My nose is not ready for fame,” she whispered.', 'when': [{'key': 'mara.knows.nia.shadow_request', 'op': 'eq', 'value': True, 'at': 'after'}]}]}, {'scene': 'tell_mara_to_bo', 'role': 'bridge', 'variants': [{'text': 'Mara told Bo the audience was not close yet. Bo tapped his chin. His parade plan suddenly needed legs, invitations, and perhaps fewer trumpets.', 'when': [{'key': 'bo.knows.audience.invited', 'op': 'eq', 'value': False, 'at': 'after'}]}]}, {'scene': 'transfer_ribbon_to_bo', 'role': 'bridge', 'variants': [{'text': 'Mara handed Bo the blue ribbon. “Catch the curtain,” she said. Bo looped it around his wrist like a heroic noodle.', 'when': [{'key': 'ribbon.owner', 'op': 'eq', 'value': 'bo', 'at': 'after'}]}, {'text': 'The ribbon changed hands, from Mara to Bo, and became a bright blue promise against the red tangle.', 'when': [{'key': 'ribbon.owner', 'op': 'eq', 'value': 'bo', 'at': 'after'}]}]}, {'scene': 'untangle_curtain_with_ribbon', 'role': 'beat', 'variants': [{'text': 'Bo pulled gently. The ribbon caught the curtain, the curtain released Puck, and Puck swooped upward with a flap-flap-flap. “A rescue!” cried Mara. “A kite!” cried Bo. The knot, at least, had nothing left to say.', 'when': [{'key': 'curtain.tangled', 'op': 'eq', 'value': False, 'at': 'after'}]}]}, {'scene': 'transfer_ribbon_to_nia', 'role': 'bridge', 'variants': [{'text': 'Mara placed the blue ribbon in Nia’s hands. “For your secret screen,” she said. Nia held it carefully, as if it were a doorway only she could open.', 'when': [{'key': 'ribbon.owner', 'op': 'eq', 'value': 'nia', 'at': 'after'}]}]}, {'scene': 'agree_small_role', 'role': 'beat', 'variants': [{'text': 'Nia swallowed, then nodded. “I can make one small shadow.” Mara squeezed her hand. “Small shadows can have enormous ears.” Nia stepped toward the curtain, braver by exactly one bright button.', 'when': [{'key': 'nia.agreed', 'op': 'eq', 'value': True, 'at': 'after'}, {'key': 'nia.brave', 'op': 'eq', 'value': 1, 'at': 'after'}]}]}, {'scene': 'fold_curtain_into_shadow_screen', 'role': 'beat', 'variants': [{'text': 'Nia and Mara folded the curtain into a shadow screen. Behind it, their fingers became rabbits, clouds, and one very suspicious potato. Nia laughed softly. The screen glowed, ready for a story no staring face could spoil.', 'when': [{'key': 'curtain.form', 'op': 'eq', 'value': 'shadow_screen', 'at': 'after'}]}]}, {'scene': 'invite_audience_close', 'role': 'beat', 'variants': [{'text': 'Bo marched to the courtyard edge and called, “Follow the paper sun!” The audience came closer, then closer still, until the stage had feet all around it. Bo’s grand plan suddenly had exactly the number of spectators it needed.', 'when': [{'key': 'audience.invited', 'op': 'eq', 'value': True, 'at': 'after'}]}]}, {'scene': 'place_sun_high', 'role': 'bridge', 'variants': [{'text': 'Bo lifted the paper sun high above the stage. It wobbled magnificently, like a pancake escaping breakfast.', 'when': [{'key': 'sun.location', 'op': 'eq', 'value': 'high', 'at': 'after'}]}]}, {'scene': 'place_clouds_low', 'role': 'bridge', 'variants': [{'text': 'Mara set the cloud puppets bobbing low. They drifted around Bo’s knees, soft and lumpy as traveling sheep.', 'when': [{'key': 'clouds.location', 'op': 'eq', 'value': 'low', 'at': 'after'}]}]}, {'scene': 'perform_kite_rescue', 'role': 'beat', 'variants': [{'text': 'Bo and Mara sent Puck sailing above the curtain. The blue ribbon hummed, Puck dipped, and Bo caught him with a triumphant “Ta-da!” Nia laughed from the wings as the audience clapped like a flock of tiny wings.', 'when': [{'key': 'stage.performance', 'op': 'eq', 'value': 'kite_rescue', 'at': 'after'}, {'key': 'audience.response', 'op': 'eq', 'value': 'delighted', 'at': 'after'}]}]}, {'scene': 'perform_shadow_story', 'role': 'beat', 'variants': [{'text': 'Behind the glowing screen, Nia’s paper hands discovered a moon, a shy rabbit, and a potato who wanted a hat. The audience leaned close and stayed wonderfully quiet. Nia’s little shadow bowed before her face ever needed to.', 'when': [{'key': 'stage.performance', 'op': 'eq', 'value': 'shadow_story', 'at': 'after'}, {'key': 'audience.response', 'op': 'eq', 'value': 'quietly_charmed', 'at': 'after'}]}]}, {'scene': 'perform_weather_parade', 'role': 'beat', 'variants': [{'text': 'Bo led the weather parade beneath the paper sun, with cloud puppets bobbing behind him and Mara marching beside a giggling audience. Nia carried a cloud that sneezed confetti. The grand finale had become gloriously, wonderfully mobile.', 'when': [{'key': 'stage.performance', 'op': 'eq', 'value': 'weather_parade', 'at': 'after'}, {'key': 'audience.response', 'op': 'eq', 'value': 'delighted', 'at': 'after'}]}]}, {'scene': 'bow_and_share_paper_sun', 'role': 'bridge', 'variants': [{'text': 'The children bowed together, then held the paper sun between them so its warm yellow grin shone on every face.', 'when': [{'key': 'stage.performance', 'op': 'ne', 'value': 'none', 'at': 'before'}]}]}], 'endings': [{'text': 'Puck sailed above the curtain, tugging the blue ribbon into a singing arc. Below, Bo and Mara bowed while the courtyard clapped in a rhythm like little wings. Even the rescued puppet seemed to know he had found the finest possible sky.', 'when': [{'key': 'stage.performance', 'op': 'eq', 'value': 'kite_rescue', 'at': 'after'}, {'key': 'audience.response', 'op': 'eq', 'value': 'delighted', 'at': 'after'}]}, {'text': 'The blue ribbon hummed, Puck swooped, and the applause fluttered up to meet him. When the children bowed, the red curtain looked less like a problem and more like the doorway to a very excellent breeze.', 'when': [{'key': 'stage.performance', 'op': 'eq', 'value': 'kite_rescue', 'at': 'after'}, {'key': 'audience.response', 'op': 'eq', 'value': 'delighted', 'at': 'after'}]}, {'text': 'Nia’s paper hands glowed across the shadow screen: rabbit, moon, potato, hat. When the story ended, the audience left the stool in a neat moon-shaped circle around her. Nia peeked out and smiled at the circle’s quiet sparkle.', 'when': [{'key': 'stage.performance', 'op': 'eq', 'value': 'shadow_story', 'at': 'after'}, {'key': 'audience.response', 'op': 'eq', 'value': 'quietly_charmed', 'at': 'after'}]}, {'text': 'The courtyard stayed hushed for one soft breath after Nia’s final shadow bowed. Then everyone smiled, including Nia. Around the low stool, the audience made a moon of themselves, and her paper hands rested happily inside it.', 'when': [{'key': 'stage.performance', 'op': 'eq', 'value': 'shadow_story', 'at': 'after'}, {'key': 'audience.response', 'op': 'eq', 'value': 'quietly_charmed', 'at': 'after'}]}, {'text': 'Bo marched under the paper sun with clouds bobbing behind him, while Mara led the cheerful crowd across the courtyard. The once-serious stage stood empty and pleased, as if it had grown a pair of dancing feet.', 'when': [{'key': 'stage.performance', 'op': 'eq', 'value': 'weather_parade', 'at': 'after'}, {'key': 'audience.response', 'op': 'eq', 'value': 'delighted', 'at': 'after'}]}, {'text': 'The paper sun traveled over a wandering sky: Bo beneath it, cloud puppets behind, and the audience trotting along. Nia’s confetti-sneezing cloud gave one last puff, and the whole courtyard became a parade-shaped grin.', 'when': [{'key': 'stage.performance', 'op': 'eq', 'value': 'weather_parade', 'at': 'after'}, {'key': 'audience.response', 'op': 'eq', 'value': 'delighted', 'at': 'after'}]}], 'lexicon': []}

def render(run, rng):
    return render_book(run, rng, BOOK)

def generate(seed, prose_seed=None):
    return realize(solve(build(seed), seed), render, seed if prose_seed is None else prose_seed)
